package org.atomos.radio;

import android.test.InstrumentationTestCase;
import org.json.*;
import java.io.*;
import java.nio.ByteBuffer;
import java.nio.ByteOrder;
import java.nio.file.Files;
import java.util.*;
import java.util.zip.GZIPInputStream;

/** Public synthetic packet corpus: 750 frames, 500 UDP, 250 TCP, two late DNS queries. */
public final class PagingTest extends InstrumentationTestCase {
    private File fixture()throws Exception {
        File f=File.createTempFile("synthetic-page-",".pcap",getInstrumentation().getTargetContext().getCacheDir());
        try(InputStream in=new GZIPInputStream(new ByteArrayInputStream(Base64.getDecoder().decode(FIXTURE_GZIP)));OutputStream out=new FileOutputStream(f)){byte[] b=new byte[4096];int n;while((n=in.read(b))>=0)out.write(b,0,n);}return f;
    }
    private JSONObject page(File file,String filter,String query,int offset,int size,String hash)throws Exception{return new JSONObject(PacketDecoder.decodePage(file,filter,query,offset,size,hash));}
    public void testUdpPagesCoverAllMatchesAndKeepLateDetails()throws Exception {
        File f=fixture();try{Set<Integer> indices=new HashSet<>();int[] first={1,301,601},last={299,599,749},counts={200,200,100};String hash=null;
            for(int i=0;i<3;i++){JSONObject r=page(f,"UDP","",i*200,200,hash);hash=r.getString("file_sha256");assertEquals(FIXTURE_SHA,hash);assertTrue(r.getBoolean("complete"));assertEquals(750,r.getInt("packets_seen"));JSONObject meta=r.getJSONObject("page");JSONArray packets=r.getJSONArray("packets");assertEquals(500,meta.getInt("total_matches"));assertEquals(counts[i],packets.length());assertEquals(i<2,meta.getBoolean("has_next"));assertEquals(first[i],packets.getJSONObject(0).getInt("index"));assertEquals(last[i],packets.getJSONObject(packets.length()-1).getInt("index"));
                for(int j=0;j<packets.length();j++){JSONObject p=packets.getJSONObject(j);assertTrue(indices.add(p.getInt("index")));assertTrue(p.has("udp_payload_text"));}
            }assertEquals(500,indices.size());assertTrue(indices.contains(749));
            JSONObject legacy=new JSONObject(PacketDecoder.decode(f)),all=page(f,"All","",0,200,hash);assertEquals(200,legacy.getJSONArray("packets").length());assertEquals(legacy.getJSONArray("packets").toString(),all.getJSONArray("packets").toString());assertFalse(legacy.has("page"));
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testGlobalProtocolAndSearchFindLateDnsAndPayload()throws Exception {
        File f=fixture();try{
            JSONObject dns=page(f,"DNS","",0,200,FIXTURE_SHA);assertEquals(2,dns.getJSONObject("page").getInt("total_matches"));assertEquals(452,dns.getJSONArray("packets").getJSONObject(0).getInt("index"));assertEquals(749,dns.getJSONArray("packets").getJSONObject(1).getInt("index"));
            JSONObject query=page(f,"UDP"," PAGE0749.EXAMPLE.TEST ",0,200,FIXTURE_SHA);assertEquals(1,query.getJSONObject("page").getInt("total_matches"));assertEquals(749,query.getJSONArray("packets").getJSONObject(0).getInt("index"));
            JSONObject text=page(f,"UDP","SYNTHETIC-PAGE-0701",0,200,FIXTURE_SHA);assertEquals(1,text.getJSONObject("page").getInt("total_matches"));assertEquals(701,text.getJSONArray("packets").getJSONObject(0).getInt("index"));
            JSONObject broad=page(f,"UDP","SYNTHETIC-PAGE-",400,200,FIXTURE_SHA);assertEquals(498,broad.getJSONObject("page").getInt("total_matches"));assertEquals(98,broad.getJSONArray("packets").length());
            JSONObject tcp=page(f,"TCP","",200,200,FIXTURE_SHA);assertEquals(250,tcp.getJSONObject("page").getInt("total_matches"));assertEquals(50,tcp.getJSONArray("packets").length());assertEquals(603,tcp.getJSONArray("packets").getJSONObject(0).getInt("index"));assertEquals(750,tcp.getJSONArray("packets").getJSONObject(49).getInt("index"));
            assertEquals(0,page(f,"TLS","",0,200,FIXTURE_SHA).getJSONObject("page").getInt("total_matches"));
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testPinnedSourceRejectsChangedBytesAndAllowsExplicitRepin()throws Exception {
        File f=fixture();try{byte[] b=Files.readAllBytes(f.toPath());b[24]^=1;Files.write(f.toPath(),b);
            JSONObject r=page(f,"UDP","",0,200,FIXTURE_SHA);assertEquals("source_changed",r.getString("status"));assertFalse(r.getBoolean("complete"));assertEquals(0,r.getJSONArray("packets").length());assertEquals(0,r.getInt("packets_seen"));assertFalse(r.getJSONObject("page").getBoolean("valid"));
            JSONObject fresh=page(f,"UDP","",0,200,null);assertTrue(fresh.getBoolean("complete"));assertFalse(FIXTURE_SHA.equals(fresh.getString("file_sha256")));assertEquals(500,fresh.getJSONObject("page").getInt("total_matches"));
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testPostScanStatChangeDropsReturnedRows()throws Exception {
        File f=fixture();try{final long actual=f.length();File changingStat=new File(f.getPath()){int calls;@Override public long length(){return ++calls==1?actual:actual+1;}};
            JSONObject r=page(changingStat,"UDP","",0,200,FIXTURE_SHA);assertEquals("source_changed",r.getString("status"));assertEquals(750,r.getInt("packets_seen"));assertEquals(0,r.getJSONArray("packets").length());assertEquals(0,r.getJSONObject("page").getInt("total_matches"));assertFalse(r.getJSONObject("page").getBoolean("valid"));
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testPageBoundsAndOffsetAfterMatches()throws Exception {
        File f=fixture();try{JSONObject beyond=page(f,"UDP","",501,200,FIXTURE_SHA);assertEquals(500,beyond.getJSONObject("page").getInt("total_matches"));assertEquals(0,beyond.getJSONArray("packets").length());assertFalse(beyond.getJSONObject("page").getBoolean("has_next"));assertTrue(beyond.getJSONObject("page").isNull("next_offset"));
            for(int[] pair:new int[][]{{-1,200},{0,0},{0,201}}){try{page(f,"All","",pair[0],pair[1],null);fail("invalid page accepted");}catch(IllegalArgumentException expected){}}
            try{page(f,"bogus","",0,200,null);fail("invalid filter accepted");}catch(IllegalArgumentException expected){}
            try{page(f,"All","",0,200,"bad hash");fail("invalid source pin accepted");}catch(IllegalArgumentException expected){}
            char[] large=new char[257];Arrays.fill(large,'x');try{page(f,"All",new String(large),0,200,null);fail("unbounded query accepted");}catch(IllegalArgumentException expected){}
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testMalformedTailReportsPrefixMatchCount()throws Exception {
        File f=fixture();try{byte[] bytes=Files.readAllBytes(f.toPath());Files.write(f.toPath(),Arrays.copyOf(bytes,bytes.length-5));JSONObject r=page(f,"DNS","",0,200,null);assertEquals("malformed",r.getString("status"));assertFalse(r.getBoolean("complete"));assertEquals(749,r.getInt("packets_seen"));assertEquals(2,r.getJSONObject("page").getInt("total_matches"));assertFalse(r.getJSONObject("page").getBoolean("matches_complete"));
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testCooperativeCancellationPreservesInterrupt()throws Exception {
        File f=fixture();try{Thread.currentThread().interrupt();try{PacketDecoder.decodePage(f,"All","",0,200,null);fail("cancelled scan returned");}catch(InterruptedIOException expected){assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();}
        }finally{Files.deleteIfExists(f.toPath());}
    }
    public void testPacketScanLimitIsNotAFullMatchCount()throws Exception {
        File f=File.createTempFile("synthetic-limit-",".pcap",getInstrumentation().getTargetContext().getCacheDir());try{
            byte[] header=ByteBuffer.allocate(24).order(ByteOrder.LITTLE_ENDIAN).putInt(0xa1b2c3d4).putShort((short)2).putShort((short)4).putInt(0).putInt(0).putInt(65535).putInt(101).array();byte[] row=new byte[44];ByteBuffer v=ByteBuffer.wrap(row).order(ByteOrder.LITTLE_ENDIAN);v.putInt(1700000000).putInt(0).putInt(28).putInt(28);row[16]=0x45;row[19]=28;row[24]=64;row[25]=17;row[40]=0;row[41]=8;
            try(OutputStream out=new BufferedOutputStream(new FileOutputStream(f))){out.write(header);for(int i=0;i<100001;i++)out.write(row);}
            JSONObject r=page(f,"UDP","",99999,200,null);assertEquals("limit_exceeded",r.getString("status"));assertFalse(r.getBoolean("complete"));assertEquals(100000,r.getInt("packets_seen"));assertEquals(100000,r.getJSONObject("page").getInt("total_matches"));assertFalse(r.getJSONObject("page").getBoolean("matches_complete"));assertEquals(1,r.getJSONArray("packets").length());assertEquals(100000,r.getJSONArray("packets").getJSONObject(0).getInt("index"));
        }finally{Files.deleteIfExists(f.toPath());}
    }
    private static final String FIXTURE_SHA="7ebe2e1962ea5e5d6e2fe93ba37234bd9ecc1456853c4be131e8d58cc5ab1325";
    private static final String FIXTURE_GZIP="";
}
